import {model,NODES} from './constellation.js';
import {fresh,DAY} from './engine.js';
export function learningEvidence(raw,now=Date.now()){
 const state={...fresh(),grade:Number.isInteger(raw?.grade)?raw.grade:1,attempts:(Array.isArray(raw?.attempts)?raw.attempts:[]).filter(a=>a&&NODES.some(n=>n.id===a.node)&&Number.isFinite(a.at)&&a.at<=now&&Number.isFinite(a.ms)),sessions:Array.isArray(raw?.sessions)?raw.sessions:[]};
 const m=model(state,now);
 return {totalFirstAttempts:state.attempts.length,practiceDays:new Set(state.attempts.map(a=>Math.floor(a.at/DAY))).size,completedLevels:Object.values(m.nodes).filter(n=>n.complete).map(n=>n.order),rememberedNow:Object.values(m.nodes).filter(n=>n.mastered).map(n=>n.order),suggestedNext:m.recommendation.name,skills:Object.values(m.nodes).filter(n=>n.history.length).map(n=>({level:n.order,name:n.name,completionEarned:n.complete,currentStage:n.stage,attempts:n.history.length,independentCorrect:n.history.filter(a=>a.ok&&!a.hint).length,firstAttemptMistakes:n.history.filter(a=>!a.ok).length,hintAssisted:n.history.filter(a=>a.hint).length,recentIndependentAccuracy:Math.round(n.accuracy*100),successfulDelayedChecks:n.checks,reviewSuggested:n.due||n.fragile,daysSincePractice:Math.floor((now-n.lastAt)/DAY),formats:[...new Set(n.history.map(a=>a.form))].filter(x=>['visual','story','symbolic'].includes(x)),recentChallengeLevels:[...new Set(n.history.slice(-8).map(a=>a.level))]})),limits:'First attempts only. Retries, feelings, ability, personality, diagnoses and life outside this app are not measured. Completion means initial fluent evidence; durable retention is tracked separately. Recent accuracy covers up to eight attempts and different challenge sizes.'};
}
